<?php require_once __DIR__.'/config/config.php';auth();if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit('Method not allowed');}check_csrf();$id=(int)($_POST['id']??0);try{$s=db()->prepare('SELECT student_code FROM students WHERE id=?');$s->execute([$id]);$r=$s->fetch();if(!$r)flash('Student not found.','error');else{db()->beginTransaction();db()->prepare('DELETE FROM students WHERE id=?')->execute([$id]);db()->prepare('INSERT INTO activity_logs(admin_id,action,entity_type,entity_id,details,ip_address) VALUES(?,?,?,?,?,?)')->execute([$_SESSION['admin_id'],'student.deleted','student',$id,$r['student_code'],$_SERVER['REMOTE_ADDR']??null]);db()->commit();flash('Student deleted successfully.');}}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();flash('Unable to delete this student.','error');}header('Location: dashboard.php');exit;